package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.get;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;

final class TypedRelationshipsAcceptance {
 static final String TYPES="/api/openservice/relationship-types";
 static String api(String table,String id){return "/api/openservice/records/"+table+"/"+id+"/relations";}
 static Map<String,Object> config(int revision,boolean impact){return map("revision",revision,"source_table","cmdb_ci","target_table","cmdb_ci","forward_label","Runs on <script>","inverse_label","Runs applications","propagates",impact,"active",true);}
 static String type(WorkflowSupport h,Map<String,Object> body)throws Exception{return object(result(h.json("POST",TYPES,body,auth("admin"))).get("type")).get("type_id").toString();}
 static String record(WorkflowSupport h,String table,String summary)throws Exception{return result(h.json("POST","/api/now/table/"+table,map("short_description",summary),auth("admin"))).get("sys_id").toString();}
 static String query(String type,String direction,String related){return "?type_id="+type+"&direction="+direction+"&related_id="+related;}
 static Map<String,Object> command(WorkflowSupport h,String table,String record,String type,String direction,String related)throws Exception{var body=object(get(h,api(table,record)+"/review"+query(type,direction,related),"admin").get("command"));body.put("reason","Reviewed current endpoint meaning <script>");return body;}
 static Map<String,Object> change(WorkflowSupport h,String table,String record,String type,String direction,String related)throws Exception{return result(h.json("POST",api(table,record),command(h,table,record,type,direction,related),auth("admin")));}
 static List<Map<String,Object>> impact(WorkflowSupport h,String id)throws Exception{return objects(get(h,PlatformOperationsAcceptance.ROOT+"dependencies/"+id,"admin").get("impacted"));}
 static void run(WorkflowSupport h)throws Exception {
  String type=type(h,config(0,true)),app=record(h,"cmdb_ci","Application"),host=record(h,"cmdb_ci","Hosting system"),other=record(h,"cmdb_ci","Associated system");var empty=get(h,api("cmdb_ci",app),"admin");assertTrue(objects(empty.get("links")).isEmpty());var linked=change(h,"cmdb_ci",app,type,"outbound",host);var edge=objects(linked.get("links")).getFirst();assertEquals("Runs on <script>",edge.get("label"));assertEquals(host,object(edge.get("related")).get("sys_id"));assertEquals("Runs applications",objects(get(h,api("cmdb_ci",host),"admin").get("links")).getFirst().get("label"));assertTrue(impact(h,host).stream().anyMatch(r->r.get("sys_id").equals(app)));assertEquals(409,h.json("DELETE","/api/now/table/cmdb_ci/"+app,map(),auth("admin")).statusCode());
  var assoc=config(0,false);assoc.put("forward_label","Communicates with");assoc.put("inverse_label","Receives communication");String association=type(h,assoc);change(h,"cmdb_ci",app,association,"outbound",other);assertTrue(impact(h,other).isEmpty());change(h,"cmdb_ci",app,association,"outbound",host);assertEquals(3,objects(get(h,api("cmdb_ci",app),"admin").get("links")).size());
  var disable=config(1,true);disable.put("active",false);result(h.json("POST",TYPES+"/"+type,disable,auth("admin")));assertTrue(impact(h,host).stream().anyMatch(r->r.get("sys_id").equals(app)));change(h,"cmdb_ci",host,type,"inbound",app);assertTrue(impact(h,host).isEmpty());var removed=objects(get(h,api("cmdb_ci",app),"admin").get("links")).stream().filter(r->r.get("type_id").equals(type)).findFirst().orElseThrow();assertEquals(0,removed.get("active"));assertEquals(2,objects(removed.get("history")).size());assertEquals(409,h.json("POST",api("cmdb_ci",app),command(h,"cmdb_ci",app,type,"outbound",host),auth("admin")).statusCode());disable.put("revision",2);disable.put("active",true);result(h.json("POST",TYPES+"/"+type,disable,auth("admin")));change(h,"cmdb_ci",app,type,"outbound",host);new Store(h.environment);assertTrue(impact(h,host).stream().anyMatch(r->r.get("sys_id").equals(app)));
  var cross=config(0,false);cross.put("source_table","incident");cross.put("target_table","cmdb_ci");cross.put("forward_label","Affects");cross.put("inverse_label","Affected by incident");String crossType=type(h,cross),incident=record(h,"incident","Related incident");change(h,"cmdb_ci",host,crossType,"inbound",incident);assertEquals("Affects",objects(get(h,api("incident",incident),"admin").get("links")).getFirst().get("label"));change(h,"incident",incident,crossType,"outbound",host);assertEquals(204,h.json("DELETE","/api/now/table/incident/"+incident,map(),auth("admin")).statusCode());assertFalse(JSON.writeValueAsString(get(h,api("cmdb_ci",host),"admin")).contains(incident));
  try(var db=h.store.open()){assertEquals(3,db.count("SELECT COUNT(*) FROM os_relation_history WHERE relation_id=?",edge.get("relation_id")));assertEquals(5,db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action='relationship.changed'",app));}
 }
 static void configuration(WorkflowSupport h)throws Exception {
  assertTrue(objects(get(h,TYPES,"admin").get("types")).isEmpty());assertEquals(404,h.get(TYPES+"/"+id(),auth("admin")).statusCode());assertEquals(400,h.get(TYPES+"?bad=true",auth("admin")).statusCode());assertEquals(405,h.json("DELETE",TYPES,map(),auth("admin")).statusCode());
  for(var invalid:List.of(map("extra",1),map("forward_label",""),map("inverse_label","x".repeat(81)),map("active","true"),map("propagates","true"),map("source_table","incident"),map("target_table","incident"))) {var body=config(0,true);body.putAll(invalid);assertEquals(400,h.json("POST",TYPES,body,auth("admin")).statusCode(),invalid.toString());}
  var unknown=config(0,false);unknown.put("source_table","not_a_native_table");assertEquals(404,h.json("POST",TYPES,unknown,auth("admin")).statusCode());String type=type(h,config(0,true));assertEquals(400,h.json("POST",TYPES,config(0,true),auth("admin")).statusCode());assertEquals(409,h.json("POST",TYPES+"/"+type,config(0,true),auth("admin")).statusCode());var edit=config(1,true);edit.put("inverse_label","Hosts applications");result(h.json("POST",TYPES+"/"+type,edit,auth("admin")));String a=record(h,"cmdb_ci","Source"),b=record(h,"cmdb_ci","Target");change(h,"cmdb_ci",a,type,"outbound",b);for(var difference:List.of(map("source_table","incident","propagates",false),map("target_table","incident","propagates",false),map("forward_label","Changed meaning"),map("inverse_label","Changed inverse"),map("propagates",false))){var body=new LinkedHashMap<>(edit);body.put("revision",2);body.putAll(difference);assertEquals(409,h.json("POST",TYPES+"/"+type,body,auth("admin")).statusCode());}
  var html=map("revision","0","source_table","cmdb_ci","target_table","cmdb_ci","forward_label","HTML meaning","inverse_label","HTML inverse","propagates","false","active","yes");assertEquals(400,h.protectedForm("/admin/relationship-types/new",html,auth("admin")).statusCode());
 }
 static void boundaries(WorkflowSupport h)throws Exception {
  String type=type(h,config(0,true)),a=record(h,"cmdb_ci","Source"),b=record(h,"cmdb_ci","Target");String path=api("cmdb_ci",a);assertEquals(401,h.get(path,null).statusCode());assertEquals(400,h.get(path+"?extra=1",auth("admin")).statusCode());assertEquals(405,h.json("DELETE",path,map(),auth("admin")).statusCode());assertEquals(405,h.json("POST",path+"/choose",map(),auth("admin")).statusCode());assertEquals(400,h.get(path+"/review",auth("admin")).statusCode());assertEquals(400,h.get(path+"/choose?type_id="+type,auth("admin")).statusCode());for(String direction:List.of("unknown",""))assertEquals(400,h.get(path+"/review"+query(type,direction,b),auth("admin")).statusCode());assertEquals(400,h.get(path+"/review"+query(type,"outbound",a),auth("admin")).statusCode());assertEquals(404,h.get(path+"/review"+query(type,"outbound",id()),auth("admin")).statusCode());String incident=record(h,"incident","Wrong table");assertEquals(400,h.get(api("incident",incident)+"/review"+query(type,"outbound",b),auth("admin")).statusCode());assertEquals(400,h.get(api("incident",incident)+"/choose?type_id="+type+"&direction=outbound",auth("admin")).statusCode());assertEquals(200,h.get(path+"/choose?type_id="+type+"&direction=inbound&q=Target",auth("admin")).statusCode());
  var cmd=command(h,"cmdb_ci",a,type,"outbound",b);for(var invalid:List.of(map("extra",1),map("remove","false"),map("remove",true),map("reason",""))){var body=new LinkedHashMap<>(cmd);body.putAll(invalid);assertEquals(400,h.json("POST",path,body,auth("admin")).statusCode());}for(String revision:List.of("revision","type_revision","record_revision","related_revision")){var stale=new LinkedHashMap<>(cmd);stale.put(revision,999);assertEquals(409,h.json("POST",path,stale,auth("admin")).statusCode());}
  result(h.json("PATCH","/api/now/table/cmdb_ci/"+b,map("description","Changed after review"),auth("admin")));assertEquals(409,h.json("POST",path,cmd,auth("admin")).statusCode());change(h,"cmdb_ci",a,type,"outbound",b);var wrong=command(h,"cmdb_ci",a,type,"outbound",b);wrong.put("remove",false);assertEquals(400,h.json("POST",path,wrong,auth("admin")).statusCode());var disabled=config(1,true);disabled.put("active",false);result(h.json("POST",TYPES+"/"+type,disabled,auth("admin")));assertEquals(409,h.get(path+"/choose?type_id="+type+"&direction=outbound",auth("admin")).statusCode());
  var html=new LinkedHashMap<String,Object>();command(h,"cmdb_ci",a,type,"outbound",b).forEach((k,v)->html.put(k,v.toString()));html.put("remove","yes");assertEquals(400,h.protectedForm("/record/cmdb_ci/"+a+"/relations",html,auth("admin")).statusCode());
 }
 static void authority(WorkflowSupport h)throws Exception {
  h.account("RelationReader","reader");h.account("RelationStaff","agent");String type=type(h,config(0,true)),a=record(h,"cmdb_ci","Visible source"),b=record(h,"cmdb_ci","Secret target");var cmd=command(h,"cmdb_ci",a,type,"outbound",b);assertEquals(403,h.get(TYPES,auth("RelationStaff")).statusCode());assertEquals(403,h.json("POST",api("cmdb_ci",a),cmd,auth("RelationStaff")).statusCode());assertEquals(403,h.get(api("cmdb_ci",a)+"/review"+query(type,"outbound",b),auth("RelationStaff")).statusCode());assertEquals(403,h.get(api("cmdb_ci",a)+"/choose?type_id="+type+"&direction=outbound",auth("RelationStaff")).statusCode());change(h,"cmdb_ci",a,type,"outbound",b);assertEquals(1,objects(get(h,api("cmdb_ci",a),"RelationReader").get("links")).size());assertTrue(objects(get(h,api("cmdb_ci",a),"RelationReader").get("types")).isEmpty());ProblemInvestigationsAcceptance.access(h,"cmdb_ci",b,"private",FieldDispatchAcceptance.uid(h,"RelationStaff"));var hidden=get(h,api("cmdb_ci",a),"RelationReader");assertTrue(objects(hidden.get("links")).isEmpty());assertFalse(JSON.writeValueAsString(hidden).contains(b));ProblemInvestigationsAcceptance.access(h,"cmdb_ci",b,"workspace","");ProblemInvestigationsAcceptance.access(h,"cmdb_ci",a,"private",FieldDispatchAcceptance.uid(h,"RelationStaff"));assertTrue(objects(get(h,PlatformOperationsAcceptance.ROOT+"dependencies/"+b,"RelationReader").get("impacted")).isEmpty());ProblemInvestigationsAcceptance.access(h,"cmdb_ci",a,"workspace","");assertEquals(1,objects(get(h,PlatformOperationsAcceptance.ROOT+"dependencies/"+b,"RelationReader").get("impacted")).size());
  Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"cmdb_ci");}var hiddenLabel=new LinkedHashMap<>(original);hiddenLabel.put("field_rules",map("short_description",map("type","string","read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",hiddenLabel);try{var page=get(h,api("cmdb_ci",a),"RelationReader");assertFalse(JSON.writeValueAsString(page).contains("Secret target"));assertFalse(object(objects(page.get("links")).getFirst().get("related")).containsKey("short_description"));}finally{ReferencePickerAcceptance.writeSchema(h,"cmdb_ci",original);}
  var cross=config(0,false);cross.put("target_table","incident");cross.put("forward_label","Associated incident");String crossType=type(h,cross),incident=record(h,"incident","Restricted table target");change(h,"cmdb_ci",a,crossType,"outbound",incident);Map<String,Object> incidentSchema;try(var db=h.store.open()){incidentSchema=Service.schema(db,"incident");}var denied=new LinkedHashMap<>(incidentSchema);var roles=new LinkedHashMap<>(object(incidentSchema.getOrDefault("record_roles",map())));roles.put("read",List.of("agent"));denied.put("record_roles",roles);ReferencePickerAcceptance.writeSchema(h,"incident",denied);try{assertEquals(1,objects(get(h,api("cmdb_ci",a),"admin").get("links")).size());assertEquals(403,h.get(api("cmdb_ci",a)+"/review"+query(crossType,"outbound",incident),auth("admin")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"incident",incidentSchema);}
  var pending=command(h,"cmdb_ci",a,crossType,"outbound",incident);for(String table:List.of("cmdb_ci","incident")){var schema=table.equals("cmdb_ci")?original:incidentSchema;var policy=new LinkedHashMap<>(schema);var update=new LinkedHashMap<>(object(schema.getOrDefault("record_roles",map())));update.put("update",List.of("agent"));policy.put("record_roles",update);ReferencePickerAcceptance.writeSchema(h,table,policy);try{assertEquals(403,h.json("POST",api("cmdb_ci",a),pending,auth("admin")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,table,schema);}}
 }
 static void concurrency(WorkflowSupport h)throws Exception {
  String type=type(h,config(0,true)),a=record(h,"cmdb_ci","Concurrent source"),b=record(h,"cmdb_ci","Concurrent target");var cmd=command(h,"cmdb_ci",a,type,"outbound",b);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var start=new java.util.concurrent.CountDownLatch(1);var first=pool.submit(()->{start.await();return h.json("POST",api("cmdb_ci",a),cmd,auth("admin")).statusCode();});var second=pool.submit(()->{start.await();return h.json("POST",api("cmdb_ci",a),cmd,auth("admin")).statusCode();});start.countDown();assertEquals(Set.of(200,409),Set.of(first.get(),second.get()));}try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_typed_relation"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_relation_history"));}
  var current=command(h,"cmdb_ci",a,type,"outbound",b);change(h,"cmdb_ci",a,type,"outbound",b);assertEquals(409,h.json("POST",api("cmdb_ci",a),current,auth("admin")).statusCode());assertTrue(impact(h,b).isEmpty());
 }
 static void capacity(WorkflowSupport h)throws Exception {
  String type=type(h,config(0,false)),source=record(h,"cmdb_ci","Capacity source");var targets=new ArrayList<String>();for(int n=0;n<11;n++)targets.add(record(h,"cmdb_ci","Capacity target "+n));try(var db=h.store.open()){var types=new ArrayList<String>();types.add(type);for(int n=1;n<100;n++){String id=id();types.add(id);db.update("INSERT INTO os_relation_type(type_id,source_table,target_table,forward_label,inverse_label,propagates,active,revision) VALUES(?,'cmdb_ci','cmdb_ci',?,?,0,1,1)",id,"Retained meaning "+n,"Retained inverse "+n);}for(String kind:types)for(int n=0;n<10;n++)db.update("INSERT INTO os_typed_relation(relation_id,type_id,source_id,target_id,active,revision,updated) VALUES(?,?,?,?,1,1,?)",id(),kind,source,targets.get(n),now());db.connection.commit();}var page=get(h,api("cmdb_ci",source),"admin");assertEquals(100,objects(page.get("links")).size());assertEquals(true,page.get("truncated"));var extra=config(0,false);extra.put("forward_label","One too many");assertEquals(400,h.json("POST",TYPES,extra,auth("admin")).statusCode());assertEquals(400,h.json("POST",api("cmdb_ci",source),command(h,"cmdb_ci",source,type,"outbound",targets.get(10)),auth("admin")).statusCode());change(h,"cmdb_ci",source,type,"outbound",targets.get(0));try(var db=h.store.open()){assertEquals(1000,db.count("SELECT COUNT(*) FROM os_typed_relation"));}
 }
}
